agent_detail.agent_sql:
SELECT ?bond_type WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}
GROUP BY ?bond_type
ORDER BY DESC(COUNT(?b))
LIMIT 1

SELECT ?label WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/hasMolecule> ?molecule .
  ?molecule <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(LCASE(?element) = "h")
}
GROUP BY ?label
ORDER BY DESC(COUNT(?atom))
LIMIT 1

SELECT (AVG(?cnt) AS ?avgOxygen)
WHERE {
  {
    SELECT ?m (COUNT(?atom) AS ?cnt) WHERE {
      ?mol a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?m .
      FILTER EXISTS {
        ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "-" .
      }
      OPTIONAL {
        ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
              <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?m ;
              <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> "o" .
      }
    }
    GROUP BY ?m
  }
}

SELECT (AVG(?cnt) AS ?avgSingleBonds)
WHERE {
  {
    SELECT ?m (COUNT(?bond) AS ?cnt)
    WHERE {
      ?mol a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?m ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
      FILTER(?label = "+")
      ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
      FILTER(?bt = "-")
    }
    GROUP BY ?m
  }
}

SELECT DISTINCT ?molecule_id WHERE {
