      ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?m ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "=" .
