WHERE {
  {
    SELECT (COUNT(DISTINCT ?m1) AS ?total)
    WHERE {
      ?m1 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> "+" .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?m2) AS ?noF)
    WHERE {
      ?m2 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> "+" ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?mid2 .
      FILTER NOT EXISTS {
        ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid2 ;
           <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> "f" .
      }
    }
