  FILTER(?a1 = "TR009_12" || ?a2 = "TR009_12")
  ?bond a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_id> ?bondId ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR009" .
}

