          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?mol2 .
      ?mol2 <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> "+" .
    }
  }
}

