}

SELECT ?pct WHERE {
  {
    SELECT (COUNT(?a) AS ?total) WHERE {
      ?a a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR206" .
    }
  }
  {
    SELECT (COUNT(?a2) AS ?h) WHERE {
      ?a2 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR206" ;
          <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> "h" .
    }
  }
  BIND((ROUND((xsd:decimal(?h)/xsd:decimal(?total))*100*10000))/10000 AS ?pct)
}

SELECT ?label WHERE {
  {
    SELECT ?m (COUNT(?b) AS ?cnt) WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
      FILTER(?bt = "=")
    }
    GROUP BY ?m
    ORDER BY DESC(?cnt)
    LIMIT 1
  }
  ?mol a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?m ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}

SELECT ?bond_id WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?a1id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id2> ?a2id ;
     <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id .
  ?a1 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?a1id ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?e1 .
  ?a2 a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?a2id ;
      <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?e2 .
  FILTER(
    (LCASE(?e1) = "p" && LCASE(?e2) = "n") ||
    (LCASE(?e1) = "n" && LCASE(?e2) = "p")
  )
}

SELECT DISTINCT ?molecule_id WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?atom_id ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/molecule_id> ?molecule_id .
  BIND(STRAFTER(?atom_id, "_") AS ?ordinal)
  FILTER(xsd:integer(?ordinal) >= 21 && xsd:integer(?ordinal) <= 25)
  ?mol a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule> ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
       <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "+")
}

SELECT (AVG(?cnt) AS ?avgBonds)
WHERE {
  {
    SELECT ?atom (COUNT(?c) AS ?cnt)
    WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> "i" ;
            <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?aid .
      ?c a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected> ;
         <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Connected/atom_id> ?aid .
    }
    GROUP BY ?atom
  }
}

SELECT ?element WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/atom_id> ?atomId ;
        <http://bird-bird_toxicology-ontology-20261002-194249/ontology/vkg-bird_toxicology/Atom/element> ?element .
